<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { ClipboardDocumentIcon, CircleStackIcon, PlusIcon, TrashIcon } from '@heroicons/vue/24/outline'
import PageHeader from '../components/PageHeader.vue'
import StatusBadge from '../components/StatusBadge.vue'
import { api } from '../lib/api'
import type { Database } from '../types'
const databases = ref<Database[]>([]); const showCreate = ref(false); const selected = ref<Database | null>(null); const form = ref({ name: '', namespace: 'staging' }); const creating = ref(false)
onMounted(async () => { databases.value = await api.databases() })
const age = (date: string) => { const days = Math.max(1, Math.round((Date.now() - new Date(date).getTime()) / 86400000)); return days === 1 ? 'yesterday' : `${days} days ago` }
async function create() { creating.value = true; try { const result = await api.createDatabase(form.value); databases.value.unshift(result) } catch { databases.value.unshift({ id: `local-${Date.now()}`, ...form.value, host: `${form.value.name}-postgres.${form.value.namespace}.svc.cluster.local`, port: 5432, username: 'vertex', password: 'vertex-demo-password', connectionString: `Host=${form.value.name}-postgres.${form.value.namespace}.svc.cluster.local;Port=5432;Database=${form.value.name};Username=vertex;Password=••••••••`, status: 'Provisioning', createdAt: new Date().toISOString() }) } finally { creating.value = false; showCreate.value = false; form.value = { name: '', namespace: 'staging' } } }
async function remove(database: Database) { if (!window.confirm(`Delete ${database.name}? This uninstalls the PostgreSQL release.`)) return; await api.deleteDatabase(database.id).catch(() => undefined); databases.value = databases.value.filter((item) => item.id !== database.id) }
async function copy(value: string) { await navigator.clipboard?.writeText(value) }
</script>

<template><PageHeader eyebrow="Managed services" title="PostgreSQL" description="Provision a ready-to-use PostgreSQL instance directly into an environment with Helm-backed lifecycle management."><button class="button-primary" @click="showCreate = true"><PlusIcon class="h-4 w-4" />Create database</button></PageHeader><div class="grid gap-4 xl:grid-cols-2"><div v-for="database in databases" :key="database.id" class="surface p-5 sm:p-6"><div class="flex items-start justify-between"><div class="flex items-center gap-3"><div class="grid h-10 w-10 place-items-center rounded-xl bg-sky-400/10 text-sky-300"><CircleStackIcon class="h-5 w-5" /></div><div><h2 class="font-semibold text-white">{{ database.name }}</h2><p class="mt-1 font-mono text-[11px] text-slate-600">{{ database.namespace }}</p></div></div><StatusBadge :status="database.status" /></div><div class="mt-6 grid gap-4 rounded-xl border border-line bg-ink/40 p-4 sm:grid-cols-2"><div><p class="text-[10px] uppercase tracking-wider text-slate-600">Host</p><p class="mt-1 truncate font-mono text-xs text-slate-300" :title="database.host">{{ database.host }}</p></div><div><p class="text-[10px] uppercase tracking-wider text-slate-600">Port</p><p class="mt-1 font-mono text-xs text-slate-300">{{ database.port }}</p></div><div><p class="text-[10px] uppercase tracking-wider text-slate-600">Username</p><p class="mt-1 font-mono text-xs text-slate-300">{{ database.username }}</p></div><div><p class="text-[10px] uppercase tracking-wider text-slate-600">Created</p><p class="mt-1 text-xs text-slate-400">{{ age(database.createdAt) }}</p></div></div><div class="mt-4 flex items-center gap-2"><button class="button-secondary flex-1 text-xs" @click="selected = database">View connection details</button><button class="button-ghost text-slate-600 hover:text-rose-300" title="Delete database" @click="remove(database)"><TrashIcon class="h-4 w-4" /></button></div></div><button class="surface group flex min-h-[256px] flex-col items-center justify-center border-dashed p-5 text-center transition hover:border-sky-300/40 hover:bg-sky-300/[.03]" @click="showCreate = true"><span class="grid h-10 w-10 place-items-center rounded-xl border border-dashed border-slate-600 text-slate-500 transition group-hover:border-sky-300 group-hover:text-sky-300"><PlusIcon class="h-5 w-5" /></span><span class="mt-4 text-sm font-semibold text-slate-300">Provision PostgreSQL</span><span class="mt-1 max-w-[220px] text-xs leading-5 text-slate-600">A managed Helm release with credentials and an internal Service.</span></button></div><div class="mt-6 flex items-center gap-2 text-xs text-slate-600"><span class="h-1.5 w-1.5 rounded-full bg-sky-300" />Database passwords are generated and stored as Kubernetes Secrets.</div><Teleport to="body"><div v-if="selected" class="fixed inset-0 z-50 flex items-center justify-center bg-black/75 p-4 backdrop-blur-sm"><div class="w-full max-w-xl rounded-2xl border border-line bg-[#0d1a2c] shadow-2xl"><div class="flex items-start justify-between border-b border-line p-6"><div><p class="eyebrow text-sky-300">Connection details</p><h2 class="mt-2 text-xl font-bold text-white">{{ selected.name }}</h2></div><button class="button-ghost" @click="selected = null">×</button></div><div class="space-y-4 p-6"><div><p class="mb-2 text-xs font-semibold text-slate-400">Connection string</p><div class="flex items-center gap-2"><code class="min-w-0 flex-1 overflow-x-auto rounded-lg border border-line bg-ink px-3 py-3 font-mono text-xs text-slate-300">{{ selected.connectionString }}</code><button class="button-ghost" @click="copy(selected.connectionString)"><ClipboardDocumentIcon class="h-4 w-4" /></button></div></div><div class="grid grid-cols-2 gap-3"><div class="rounded-lg border border-line bg-ink/50 p-3"><p class="text-[10px] uppercase tracking-wider text-slate-600">Password</p><p class="mt-2 font-mono text-sm text-slate-300">{{ selected.password }}</p></div><div class="rounded-lg border border-line bg-ink/50 p-3"><p class="text-[10px] uppercase tracking-wider text-slate-600">Service DNS</p><p class="mt-2 truncate font-mono text-xs text-slate-300">{{ selected.host }}</p></div></div></div></div></div><div v-if="showCreate" class="fixed inset-0 z-50 flex items-center justify-center bg-black/75 p-4 backdrop-blur-sm"><div class="w-full max-w-md rounded-2xl border border-line bg-[#0d1a2c] shadow-2xl"><div class="flex items-start justify-between border-b border-line p-6"><div><p class="eyebrow text-sky-300">Helm provisioner</p><h2 class="mt-2 text-xl font-bold text-white">Create database</h2></div><button class="button-ghost" @click="showCreate = false">×</button></div><form class="space-y-5 p-6" @submit.prevent="create"><div><label class="mb-2 block text-xs font-semibold text-slate-300">Database name</label><input v-model="form.name" class="field font-mono" placeholder="checkout" required /></div><div><label class="mb-2 block text-xs font-semibold text-slate-300">Environment</label><select v-model="form.namespace" class="field"><option>staging</option><option>production</option><option>preview-pr-482</option></select></div><div class="rounded-xl border border-sky-300/15 bg-sky-300/[.04] p-4 text-xs leading-5 text-slate-500">Vertex will install the PostgreSQL chart, wait for readiness, and surface credentials when the release is healthy.</div><div class="flex justify-end gap-2 pt-2"><button type="button" class="button-secondary" @click="showCreate = false">Cancel</button><button class="button-primary" :disabled="creating">{{ creating ? 'Provisioning...' : 'Create database' }}</button></div></form></div></div></Teleport></template>

